def prof(fn, u, v, q, bounds):
    from scipy.optimize import least_squares

    def r(q):
        f = fn(u, q)
        return (f @ ls(f, v) - v).ravel()
    q = least_squares(r, q, bounds=bounds, gtol=1e-12).x
    return (q, ls(fn(u, q), v), np.std(r(q)))

def base(s, x):
    from scipy.optimize import least_squares
    p = s['panel_a']
    keep = np.linalg.norm(p['v'], axis=1) < 4
    (u, v) = (p['u'][keep], p['v'][keep])

    def f(u, q):
        return np.stack([np.ones_like(u), u, np.tanh(q[0] * u), np.sin(q[1] * np.roll(u, 2, axis=-1))], -1)

    def fit(q):
        a = f(u, q)
        w = np.array([ls(a[:, i], v[:, i]) for i in range(4)])
        return (w, (a * w).sum(-1) - v)
    q = least_squares(lambda q: fit(q)[1].ravel(), [1.8, 2.4], gtol=1e-12).x
    (w, r) = fit(q)
    z = np.array([least_squares(lambda z: (f(z, q) * w).sum(-1) - row, (row - w[:, 0]) / (w[:, 1] + w[:, 2]), gtol=1e-12).x for row in x])
    print('calibration', q, 'error', r.std(), 'weights', w, 'z range', z.min(), z.max())
    return z
